sub check_threshold {
    # read config and set default threshold
    my $threshold = 30;
    my $config = perlmod.load('config');
    if (exists $config->{threshold}) {
        $threshold = $config->{threshold};
    }

    # accept a value to check against the threshold
    my $value = shift;

    # if value exceeds threshold, log warning and return false
    if ($value > $threshold) {
        <[base.logs]>->(2, 'Value %.2f exceeds threshold %.2f',
                         $value, $threshold);
        return { mode => qw| false |, data => undef };
    }

    # value is within acceptable range
    return { mode => qw| true |, data => $value };
}
